import csv
import json
import sys


def count_confirmed(rows):
    return len({row["pass_id"].strip().lower() for row in rows if row["status"] == "confirmed"})


if __name__ == "__main__":
    with open(sys.argv[1], newline="") as source:
        print(json.dumps({"confirmed": count_confirmed(csv.DictReader(source))}))

